package dev.exodus.teleporter.domain;import java.util.UUID;public final class DroppedComponentPolicy{public enum Action{PROTECT,REMOVE}private DroppedComponentPolicy(){}public static Action action(UUID itemMatch,UUID activeMatch){return activeMatch!=null&&(itemMatch==null||itemMatch.equals(activeMatch))?Action.PROTECT:Action.REMOVE;}public static boolean shouldReturnFromVoid(double y,int minHeight,boolean hasSafePosition){return hasSafePosition&&y<minHeight;}}
